import json

def json_value(v):
    if isinstance(v, str):
        try:
            return json.loads(v)
        except Exception:
            return v
    return v

reads = data['reads']
song_lib = json_value(reads[1]['result'])
album_lib = json_value(reads[2]['result'])
liked_songs = json_value(reads[3]['result'])

# Check pagination
song_lib_total = song_lib.get('total_count', len(song_lib.get('records', [])))
album_lib_total = album_lib.get('total_count', len(album_lib.get('records', [])))
liked_songs_total = liked_songs.get('total_count', len(liked_songs.get('records', [])))

print(json.dumps({
    "queries": [],
    "facts": {
        "song_lib_total": song_lib_total,
        "album_lib_total": album_lib_total,
        "liked_songs_total": liked_songs_total,
        "song_lib_page_count": len(song_lib.get('records', [])),
        "album_lib_page_count": len(album_lib.get('records', [])),
        "liked_songs_page_count": len(liked_songs.get('records', []))
    }
}))
